// ============================================================
// FLUXA · AGENDA REQUEST  (Tools: before "Get Busy")
// Checks the x-demo-key header and asks the agenda connector for the busy times we need:
// the whole booking horizon (availability) or a window around the chosen slot (booking).
// Unauthorized requests skip the connector; the next node answers "unauthorized".
// ============================================================
const cfg = $('Config').first().json;
const req = $('Availability Webhook').first().json;
const key = (cfg.security || {}).demo_key;
const authorized = !key || key === 'CHANGE_ME_IN_N8N' || (req.headers || {})['x-demo-key'] === key;
const s = cfg.schedule, agenda = cfg.connectors.agenda, store = cfg.connectors.store;
const slot = new Date((req.body || {}).slot_iso || '');
const now = Date.now(), H = 3600000;
const from = isNaN(slot) ? new Date(now) : new Date(slot.getTime() - 12 * H);
const to = isNaN(slot) ? new Date(now + (s.horizon_days + 1) * 24 * H) : new Date(slot.getTime() + 12 * H);
return [{ json: {
  action: authorized ? 'busy' : 'skip', authorized,
  provider: agenda.provider, calendar_id: agenda.calendar_id || 'primary',
  sheet_id: store.sheet_id, tab: store.demos_tab,
  slot_minutes: s.slot_minutes, from: from.toISOString(), to: to.toISOString()
} }];

// ============================================================
// FLUXA · CHECK AVAILABILITY  (tool called by the voice agent)
// Free slots = schedule rules from Config minus the busy times returned by the agenda connector
// (Sheets "Demos" tab or Google Calendar). Rules: days, hours, length, notice, horizon in Config.
// Input (POST body from ElevenLabs): { preferred_day?: "2026-10-20" | "monday" | "lunes", language?: "es"|"en" }
// ============================================================
const cfg = $('Config').first().json;
if (!$('Agenda Request').first().json.authorized) return [{ json: { ok: false, error: 'unauthorized' } }];
const body = $('Availability Webhook').first().json.body || {};
const lang = String(body.language || 'es').toLowerCase().startsWith('en') ? 'en' : 'es';
const S = cfg.schedule, TZ = S.timezone, DUR = S.slot_minutes * 60000;
let busy = [];
try { busy = ($('Get Busy').first().json.busy || []).map(b => [new Date(b.start).getTime(), new Date(b.end).getTime()]).filter(([a, b]) => a < b); } catch (e) { busy = []; }
const isFree = (t) => !busy.some(([a, b]) => t < b && t + DUR > a);

// offset (minutes) of TZ at a given UTC instant
const tzOffset = (d) => {
  const p = new Intl.DateTimeFormat('en-US', { timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
    .formatToParts(d).reduce((a, x) => (a[x.type] = x.value, a), {});
  const asUTC = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute);
  return Math.round((asUTC - d.getTime()) / 60000);
};
// UTC Date for a wall-clock time in TZ
const local = (y, m, d, hh, mm) => { const guess = new Date(Date.UTC(y, m - 1, d, hh, mm)); return new Date(guess.getTime() - tzOffset(guess) * 60000); };
const localParts = (d) => new Intl.DateTimeFormat('en-US', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short' })
  .formatToParts(d).reduce((a, x) => (a[x.type] = x.value, a), {});
const label = (d) => new Intl.DateTimeFormat(lang === 'en' ? 'en-GB' : 'es-ES', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' }).format(d);

const DAYS = { sunday: 0, domingo: 0, monday: 1, lunes: 1, tuesday: 2, martes: 2, wednesday: 3, miercoles: 3, 'miércoles': 3, thursday: 4, jueves: 4, friday: 5, viernes: 5, saturday: 6, sabado: 6, 'sábado': 6 };
const pref = String(body.preferred_day || '').toLowerCase().trim();
const now = new Date();
const minStart = now.getTime() + S.min_notice_hours * 3600 * 1000;
const slots = [];
for (let i = 0; i < S.horizon_days && slots.length < 60; i++) {
  const p = localParts(new Date(now.getTime() + i * 86400000));
  const wd = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[p.weekday];
  if (!S.weekdays.includes(wd)) continue;
  if (pref && /^\d{4}-\d{2}-\d{2}$/.test(pref) && `${p.year}-${p.month}-${p.day}` !== pref) continue;
  if (pref && DAYS[pref] !== undefined && DAYS[pref] !== wd) continue;
  for (let m = S.start_hour * 60; m + S.slot_minutes <= S.end_hour * 60; m += S.slot_minutes) {
    const s = local(+p.year, +p.month, +p.day, Math.floor(m / 60), m % 60);
    if (s.getTime() >= minStart && isFree(s.getTime())) slots.push(s);
  }
}
// offer a few spread-out options, not all of them
const pick = [];
for (const s of slots) { if (!pick.length || s - pick[pick.length - 1] >= S.spread_hours * 3600 * 1000) pick.push(s); if (pick.length >= S.max_offers) break; }
return [{ json: {
  ok: true, timezone: TZ,
  slots: pick.map(s => ({ slot_iso: s.toISOString(), label: label(s) })),
  note: pick.length ? '' : (lang === 'en' ? 'No free slots for that day. Offer another day.' : 'No hay huecos ese día. Ofrece otro día.')
} }];

// ============================================================
// FLUXA · AGENDA REQUEST  (Tools: before "Get Busy")
// Checks the x-demo-key header and asks the agenda connector for the busy times we need:
// the whole booking horizon (availability) or a window around the chosen slot (booking).
// Unauthorized requests skip the connector; the next node answers "unauthorized".
// ============================================================
const cfg = $('Config (book)').first().json;
const req = $('Book Webhook').first().json;
const key = (cfg.security || {}).demo_key;
const authorized = !key || key === 'CHANGE_ME_IN_N8N' || (req.headers || {})['x-demo-key'] === key;
const s = cfg.schedule, agenda = cfg.connectors.agenda, store = cfg.connectors.store;
const slot = new Date((req.body || {}).slot_iso || '');
const now = Date.now(), H = 3600000;
const from = isNaN(slot) ? new Date(now) : new Date(slot.getTime() - 12 * H);
const to = isNaN(slot) ? new Date(now + (s.horizon_days + 1) * 24 * H) : new Date(slot.getTime() + 12 * H);
return [{ json: {
  action: authorized ? 'busy' : 'skip', authorized,
  provider: agenda.provider, calendar_id: agenda.calendar_id || 'primary',
  sheet_id: store.sheet_id, tab: store.demos_tab,
  slot_minutes: s.slot_minutes, from: from.toISOString(), to: to.toISOString()
} }];

// ============================================================
// FLUXA · BOOK DEMO  (tool called by the voice agent)
// Input: { name, email, company, role?, team_size?, use_case?, slot_iso, language? }
// Validates the data and that the slot is still free in the agenda connector.
// Returns { ok, row, say }. Later nodes create the event, save the row and notify the team.
// ============================================================
const cfg = $('Config (book)').first().json;
const b = $('Book Webhook').first().json.body || {};
const lang = String(b.language || 'es').toLowerCase().startsWith('en') ? 'en' : 'es';
if (!$('Agenda Request (book)').first().json.authorized) return [{ json: { ok: false, error: 'unauthorized' } }];
const fail = (error, es, en, extra = {}) => [{ json: { ok: false, error, say: lang === 'en' ? en : es, ...extra } }];
const missing = ['name', 'email', 'company', 'slot_iso'].filter(k => !String(b[k] || '').trim());
if (missing.length) return fail('missing_fields', `Me falta: ${missing.join(', ')}.`, `I still need: ${missing.join(', ')}.`, { missing });
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(b.email).trim())) return fail('invalid_email', 'Ese email no parece válido. ¿Me lo deletreas de nuevo?', 'That email does not look valid. Can you spell it again?');
const slot = new Date(b.slot_iso);
if (isNaN(slot) || slot.getTime() < Date.now()) return fail('invalid_slot', 'Ese horario no está disponible. Déjame ver otras opciones.', 'That time is not available. Let me check other options.');
const S = cfg.schedule, DUR = S.slot_minutes * 60000, t = slot.getTime();
let busy = [];
try { busy = $('Get Busy (book)').first().json.busy || []; } catch (e) { busy = []; }
if (busy.some(x => t < new Date(x.end).getTime() && t + DUR > new Date(x.start).getTime()))
  return fail('slot_taken', 'Ese hueco se acaba de ocupar. Te ofrezco otro.', 'That slot was just taken. Let me offer another one.');
const id = 'demo_' + Date.now().toString(36);
const when = new Intl.DateTimeFormat(lang === 'en' ? 'en-GB' : 'es-ES', { timeZone: S.timezone, weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' }).format(slot);
const city = S.timezone.split('/').pop().replace(/_/g, ' ');
return [{ json: {
  ok: true,
  row: { id, slot_iso: slot.toISOString(), when_madrid: when, name: String(b.name).trim(), email: String(b.email).trim().toLowerCase(),
         company: String(b.company).trim(), role: String(b.role || ''), team_size: String(b.team_size || ''), use_case: String(b.use_case || ''),
         language: lang, created_at: new Date().toISOString() },
  say: lang === 'en' ? `Done. Your demo is booked for ${when} (${city} time). You will get a confirmation by email.`
                     : `Listo. Tu demo queda reservada para el ${when} (hora de ${city}). Recibirás la confirmación por email.`
} }];

// Meeting to create in the agenda connector (Google Calendar adds the lead as guest + Meet link)
const cfg = $('Config (book)').first().json, r = $('Book').first().json.row, a = cfg.connectors.agenda, b = cfg.brand;
const end = new Date(new Date(r.slot_iso).getTime() + cfg.schedule.slot_minutes * 60000).toISOString();
return [{ json: { action: 'create', provider: a.provider, calendar_id: a.calendar_id || 'primary', booking: {
  start: r.slot_iso, end, email: r.email, summary: `${b.name} · Demo · ${r.company}`,
  description: `Lead: ${r.name}${r.role ? ' (' + r.role + ')' : ''} · ${r.company}\nEquipo: ${r.team_size || '?'}\nCaso: ${r.use_case || '?'}\nReservada por ${b.agent} (agente de voz).`
} } }];

// Booking row for the store connector (+ meeting link and event id when the agenda created one)
const cfg = $('Config (book)').first().json, st = cfg.connectors.store, ev = $('Create Event').first().json || {};
return [{ json: { provider: st.provider, sheet_id: st.sheet_id, tab: st.demos_tab,
  row: { ...$('Book').first().json.row, meet_url: ev.meet_url || '', event_id: ev.event_id || '' } } }];

// Brief for the team (only when the booking went through)
const book = $('Book').first().json;
if (!book.ok) return [];
const cfg = $('Config (book)').first().json, n = cfg.connectors.notify, r = book.row;
let ev = {}; try { ev = $('Create Event').first().json || {}; } catch (e) {}
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const city = cfg.schedule.timezone.split('/').pop().replace(/_/g, ' ');
const text = `📅 <b>Demo reservada</b>\n${esc(r.name)} · ${esc(r.company)}\n${esc(r.when_madrid)} (${esc(city)}) · ${esc(r.email)}` +
  (ev.meet_url ? `\n🎥 ${esc(ev.meet_url)}` : '') + (ev.ok === false ? `\n⚠️ No se pudo crear el evento en el calendario: ${esc(ev.error)}` : '');
return [{ json: { provider: n.provider, chat_id: n.chat_id, text } }];

// ============================================================
// FLUXA · CONFIRMATION EMAIL  (runs after Nora has the answer)
// Builds a branded HTML email (ES/EN) with "Add to Google Calendar" and Outlook links,
// and the video-call button when the agenda connector created a meeting (Google Meet).
// Output: { provider, to, subject, html, sender_name } for the Email sub-workflow. Returns no items
// (= no email) when the booking failed, the email connector is 'none' or the address is a test one.
// Brand, colours and schedule come from the Config sub-workflow.
// ============================================================
const cfg = $('Config (book)').first().json;
const B = cfg.brand || {}, EM = (cfg.connectors || {}).email || {};
let ev = {};
try { ev = $('Create Event').first().json || {}; } catch (e) { ev = {}; }
const CONFIG = {
  brand: B.name || 'Fluxa',
  agent: B.agent || 'Nora',
  tagline: B.tagline || { es: '', en: '' },
  durationMin: cfg.schedule.slot_minutes,
  timezone: cfg.schedule.timezone,
  meetingUrl: ev.meet_url || '',  // video-call link from the agenda connector; empty = the email says the link arrives before the demo
  demoDisclaimer: B.demo_disclaimer !== false,
  skipDomains: EM.skip_domains || ['example.com'],
  colors: B.colors
};

const book = $('Book').first().json;
if (!book.ok || !book.row || !EM.provider || EM.provider === 'none') return [];
const r = book.row;
const to = String(r.email || '').trim().toLowerCase();
if (!to || CONFIG.skipDomains.some(d => to.endsWith('@' + d))) return [];

const lang = r.language === 'en' ? 'en' : 'es';
const start = new Date(r.slot_iso);
const end = new Date(start.getTime() + CONFIG.durationMin * 60000);
const fmt = (opts) => new Intl.DateTimeFormat(lang === 'en' ? 'en-GB' : 'es-ES', { timeZone: CONFIG.timezone, ...opts });
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const dateLine = cap(fmt({ weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(start));
const timeLine = `${fmt({ hour: '2-digit', minute: '2-digit' }).format(start)} – ${fmt({ hour: '2-digit', minute: '2-digit' }).format(end)}`;
const firstName = String(r.name || '').trim().split(/\s+/)[0] || '';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const city = CONFIG.timezone.split('/').pop().replace(/_/g, ' ');
const T = {
  es: {
    subject: `Tu demo de ${CONFIG.brand} está confirmada · ${dateLine}, ${fmt({ hour: '2-digit', minute: '2-digit' }).format(start)}`,
    preheader: `${dateLine} · ${timeLine} (hora de ${city}). Añádela a tu calendario con un clic.`,
    hello: firstName ? `¡Hola, ${firstName}!` : '¡Hola!',
    title: 'Tu demo está confirmada',
    intro: `Gracias por hablar con ${CONFIG.agent}. Hemos reservado ${CONFIG.durationMin} minutos con un especialista de ${CONFIG.brand} para ver tu caso en directo.`,
    when: 'Cuándo', tz: `hora de ${city}`, format: `Online · ${CONFIG.durationMin} min · con un especialista`,
    gcal: 'Añadir a Google Calendar', outlook: 'Outlook / otro calendario', join: 'Unirse a la videollamada',
    linkLater: 'Te enviaremos el enlace de la videollamada antes de la demo.',
    agenda: 'Qué veremos', yourCase: 'Tu caso', company: 'Empresa',
    items: ['Tu flujo de trabajo actual y dónde se pierde tiempo.', `Un ejemplo en vivo de ${CONFIG.brand} resolviendo un caso parecido.`, 'Próximos pasos y cómo sería la puesta en marcha.'],
    change: '¿Necesitas cambiar la hora? Responde a este email y lo movemos.',
    disclaimer: `${CONFIG.brand} es una empresa ficticia: este email forma parte de una demo de portfolio de un agente de voz con IA. No habrá una reunión real.`,
    calDetails: `Demo de ${CONFIG.brand} (${CONFIG.durationMin} min) con un especialista.`
  },
  en: {
    subject: `Your ${CONFIG.brand} demo is confirmed · ${dateLine}, ${fmt({ hour: '2-digit', minute: '2-digit' }).format(start)}`,
    preheader: `${dateLine} · ${timeLine} (${city} time). Add it to your calendar in one click.`,
    hello: firstName ? `Hi ${firstName},` : 'Hi,',
    title: 'Your demo is confirmed',
    intro: `Thanks for talking to ${CONFIG.agent}. We have booked ${CONFIG.durationMin} minutes with a ${CONFIG.brand} specialist to walk through your use case live.`,
    when: 'When', tz: `${city} time`, format: `Online · ${CONFIG.durationMin} min · with a specialist`,
    gcal: 'Add to Google Calendar', outlook: 'Outlook / other calendar', join: 'Join the video call',
    linkLater: 'We will send you the video-call link before the demo.',
    agenda: 'What we will cover', yourCase: 'Your use case', company: 'Company',
    items: ['Your current workflow and where time gets lost.', `A live example of ${CONFIG.brand} solving a similar case.`, 'Next steps and what a rollout would look like.'],
    change: 'Need a different time? Reply to this email and we will move it.',
    disclaimer: `${CONFIG.brand} is a fictional company: this email is part of a portfolio demo of an AI voice agent. There will be no real meeting.`,
    calDetails: `${CONFIG.brand} demo (${CONFIG.durationMin} min) with a specialist.`
  }
}[lang];

// Calendar links (UTC times, so they land at the right local time for anyone)
const utc = (d) => d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
const title = `${CONFIG.brand} · Demo${r.company ? ' · ' + r.company : ''}`;
const details = [T.calDetails, r.use_case ? `${T.yourCase}: ${r.use_case}` : '', CONFIG.meetingUrl].filter(Boolean).join('\n');
// n8n's Code sandbox has no URLSearchParams, so build query strings by hand
const qs = (o) => Object.entries(o).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
const gcalUrl = 'https://calendar.google.com/calendar/render?' + qs({
  action: 'TEMPLATE', text: title, dates: `${utc(start)}/${utc(end)}`, details, location: CONFIG.meetingUrl || 'Online', ctz: CONFIG.timezone
});
const outlookUrl = 'https://outlook.live.com/calendar/0/deeplink/compose?' + qs({
  path: '/calendar/action/compose', rru: 'addevent', subject: title, startdt: start.toISOString(), enddt: end.toISOString(),
  body: details, location: CONFIG.meetingUrl || 'Online'
});

const C = CONFIG.colors;
const font = "'Helvetica Neue', Helvetica, Arial, sans-serif";
const button = (href, label, primary) => `
  <a href="${esc(href)}" target="_blank" style="display:inline-block;padding:14px 22px;border-radius:10px;font:600 15px ${font};text-decoration:none;${primary
    ? `background:${C.brand};color:#ffffff;` : `background:#ffffff;color:${C.brand};border:1px solid ${C.line};`}">${esc(label)}</a>`;
const row = (label, value) => value ? `
  <tr><td style="padding:6px 0;font:13px ${font};color:${C.muted};width:110px;vertical-align:top;">${esc(label)}</td>
      <td style="padding:6px 0;font:14px ${font};color:${C.ink};">${esc(value)}</td></tr>` : '';

const html = `<!doctype html>
<html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light"><title>${esc(T.title)}</title></head>
<body style="margin:0;padding:0;background:${C.bg};">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${esc(T.preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.bg};">
<tr><td align="center" style="padding:32px 16px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;">
    <!-- header -->
    <tr><td style="background:${C.brand};border-radius:16px 16px 0 0;padding:28px 32px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
        <td style="font:700 24px ${font};color:#ffffff;letter-spacing:-0.5px;">${esc(CONFIG.brand)}<span style="color:${C.accent};">.</span></td>
        <td align="right" style="font:12px ${font};color:${C.accent};">${esc(CONFIG.tagline[lang])}</td>
      </tr></table>
    </td></tr>
    <!-- hero -->
    <tr><td style="background:#ffffff;padding:32px 32px 8px;">
      <div style="display:inline-block;padding:6px 12px;border-radius:999px;background:${C.accent};font:600 12px ${font};color:${C.ink};">✓ ${esc(T.title)}</div>
      <h1 style="margin:16px 0 8px;font:700 26px/1.25 ${font};color:${C.ink};">${esc(T.hello)}</h1>
      <p style="margin:0;font:15px/1.6 ${font};color:${C.muted};">${esc(T.intro)}</p>
    </td></tr>
    <!-- date card -->
    <tr><td style="background:#ffffff;padding:24px 32px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid ${C.line};border-left:4px solid ${C.brand};border-radius:12px;">
        <tr><td style="padding:20px 22px;">
          <div style="font:600 12px ${font};color:${C.muted};text-transform:uppercase;letter-spacing:1px;">${esc(T.when)}</div>
          <div style="margin-top:6px;font:700 20px ${font};color:${C.ink};">${esc(dateLine)}</div>
          <div style="margin-top:4px;font:16px ${font};color:${C.ink};">${esc(timeLine)} <span style="color:${C.muted};">(${esc(T.tz)})</span></div>
          <div style="margin-top:10px;font:13px ${font};color:${C.muted};">${esc(T.format)}</div>
        </td></tr>
      </table>
    </td></tr>
    <!-- buttons -->
    <tr><td style="background:#ffffff;padding:0 32px 8px;">
      ${CONFIG.meetingUrl ? button(CONFIG.meetingUrl, T.join, true) + '&nbsp;' : ''}${button(gcalUrl, T.gcal, !CONFIG.meetingUrl)}&nbsp;
      ${button(outlookUrl, T.outlook, false)}
      ${CONFIG.meetingUrl || CONFIG.demoDisclaimer ? '' : `<p style="margin:14px 0 0;font:13px ${font};color:${C.muted};">${esc(T.linkLater)}</p>`}
    </td></tr>
    <!-- agenda -->
    <tr><td style="background:#ffffff;padding:24px 32px 8px;">
      <h2 style="margin:0 0 10px;font:700 16px ${font};color:${C.ink};">${esc(T.agenda)}</h2>
      ${T.items.map((it, i) => `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:0 0 8px;"><tr>
        <td style="width:26px;vertical-align:top;"><div style="width:20px;height:20px;border-radius:999px;background:${C.bg};color:${C.brand};font:700 12px/20px ${font};text-align:center;">${i + 1}</div></td>
        <td style="font:14px/1.5 ${font};color:${C.ink};">${esc(it)}</td></tr></table>`).join('')}
    </td></tr>
    <!-- summary -->
    <tr><td style="background:#ffffff;padding:8px 32px 28px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.bg};border-radius:12px;"><tr><td style="padding:14px 18px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
          ${row(T.company, r.company)}${row(T.yourCase, r.use_case)}
        </table>
      </td></tr></table>
      <p style="margin:18px 0 0;font:14px ${font};color:${C.ink};">${esc(T.change)}</p>
      <p style="margin:18px 0 0;font:14px ${font};color:${C.ink};">— ${esc(CONFIG.agent)} · ${esc(CONFIG.brand)}</p>
    </td></tr>
    <!-- footer -->
    <tr><td style="background:${C.ink};border-radius:0 0 16px 16px;padding:18px 32px;">
      <p style="margin:0;font:12px/1.5 ${font};color:${C.accent};">${esc(CONFIG.brand)} · ${esc(CONFIG.tagline[lang])}</p>
      ${CONFIG.demoDisclaimer ? `<p style="margin:6px 0 0;font:11px/1.5 ${font};color:#B9CCC6;">${esc(T.disclaimer)}</p>` : ''}
    </td></tr>
  </table>
</td></tr></table>
</body></html>`;

return [{ json: { provider: EM.provider, to, subject: T.subject, html, sender_name: B.sender_name || `${CONFIG.agent} · ${CONFIG.brand}`, gcal_url: gcalUrl, outlook_url: outlookUrl } }];

const cfg = $('Config (book)').first().json, n = cfg.connectors.notify, res = $input.first().json;
